 "content": "def transform(grid):
    """Connect the collinear pair of 2 markers as a trunk, then link other 2s to it in color 3."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    candidates = []
    by_row = {}
    by_col = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    for r, cols in by_row.items():
        if len(cols) >= 2:
            candidates.append((max(cols) - min(cols), 'h', r, min(cols), max(cols)))
    for c, rows in by_col.items():
        if len(rows) >= 2:
            candidates.append((max(rows) - min(rows), 'v', c, min(rows), max(rows)))
    if not candidates:
        return out
    _, axis, fixed, lo, hi = max(candidates, key=lambda x: x[0])

    if axis == 'h':
        for c in range(lo, hi + 1):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r != fixed and lo <= c <= hi:
                for rr in range(min(r, fixed), max(r, fixed) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
        for r in range(lo, hi + 1):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
            if c != fixed and lo <= r <= hi:
                for cc in range(min(c, fixed), max(c, fixed) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
